<?php $heading='Tahapan Pengajuan PBG'; $top_actions='<a class="btn" href="'.base_url('pengajuan-pbg').'">Kembali ke Daftar</a>'; $this->load->view('pbg_pu/header',compact('heading','top_actions','nama_pengguna')); $labels=array(1=>'Pendaftaran Permohonan',2=>'Pemeriksaan Kelengkapan Data',3=>'Verifikasi Hasil Perbaikan',4=>'Pemeriksaan Selesai'); ?>
<div class="steps"><?php foreach($labels as $n=>$l):?><a href="<?= base_url('pengajuan-pbg/tahap/'.$row['id'].'/'.$n) ?>" class="step <?= $n<$row['tahap']?'done':($n===$tahap?'current':'') ?>"><b><?= $n<$row['tahap']?'✓':$n ?>. <?= $l ?></b><small><?= $n===$row['tahap']?'Tahap aktif':'Lihat halaman tahap' ?></small></a><?php endforeach;?></div>
<?php if($this->session->flashdata('sukses')):?><div class="notice"><?= htmlspecialchars($this->session->flashdata('sukses')) ?></div><?php endif;?>
<div class="card"><h2 style="margin-top:0">Tahap <?= $tahap ?> — <?= $labels[$tahap] ?></h2>
<?php if($tahap===1):?><p>Halaman ini menampilkan data pendaftaran dan dokumen yang dimasukkan oleh petugas PU.</p><div class="detail-grid"><div><small>No. Permohonan</small><b><?= htmlspecialchars($row['no_permohonan']) ?></b></div><div><small>Status</small><span class="badge <?= $row['status'] ?>"><?= ucfirst($row['status']) ?></span></div><div><small>Nama Pemohon</small><?= htmlspecialchars($row['nama_pemohon']) ?></div><div><small>NIK</small><?= htmlspecialchars($row['nik']?:'—') ?></div><div><small>Nomor HP</small><?= htmlspecialchars($row['no_hp']) ?></div><div><small>Email</small><?= htmlspecialchars($row['email']?:'—') ?></div><div class="full"><small>Alamat Bangunan</small><?= htmlspecialchars($row['alamat_bangunan']) ?></div><div><small>Jenis Bangunan</small><?= htmlspecialchars($row['jenis_bangunan']) ?></div><div><small>Luas</small><?= htmlspecialchars($row['luas_bangunan']?:'—') ?> m²</div></div>
<?php elseif($tahap===2):?><p>PU memeriksa kelengkapan data pemohon dan seluruh dokumen persyaratan.</p><div class="table-wrap"><table style="min-width:700px"><thead><tr><th>Dokumen</th><th>Ketersediaan</th></tr></thead><tbody><?php foreach($files as $f=>$l):?><tr><td><?= htmlspecialchars($l) ?></td><td><?= empty($row[$f])?'<span class="badge ditolak">Belum ada</span>':'<span class="badge disetujui">✓ Tersedia</span>' ?></td></tr><?php endforeach;?></tbody></table></div>
<?php elseif($tahap===3):?><p>PU mengendalikan verifikasi hasil perbaikan. Catatan proses terakhir ditampilkan agar pemeriksaan konsisten.</p><div class="notice"><b>Catatan PU:</b><br><?= nl2br(htmlspecialchars($row['catatan_admin']?:'Belum ada catatan.')) ?></div>
<?php else:?><p>Ringkasan keputusan akhir permohonan PBG.</p><div class="detail-grid"><div><small>No. Permohonan</small><?= htmlspecialchars($row['no_permohonan']) ?></div><div><small>Keputusan</small><span class="badge <?= $row['status'] ?>"><?= ucfirst($row['status']) ?></span></div><div class="full"><small>Catatan keputusan</small><?= nl2br(htmlspecialchars($row['catatan_admin']?:'—')) ?></div></div><?php endif;?>

<h2 class="section-title">Kontrol Tahap oleh PU</h2><?= form_open('pengajuan-pbg/ubah-tahap/'.$row['id']) ?><div class="grid"><div><label>Tahap</label><select name="tahap"><?php foreach($labels as $n=>$l):?><option value="<?= $n ?>" <?= $row['tahap']==$n?'selected':'' ?>><?= $n ?> — <?= $l ?></option><?php endforeach;?></select></div><div><label>Status</label><select name="status"><?php foreach(array('diajukan'=>'Diajukan','diverifikasi'=>'Diverifikasi','disetujui'=>'Disetujui','ditolak'=>'Ditolak') as $k=>$l):?><option value="<?= $k ?>" <?= $row['status']===$k?'selected':'' ?>><?= $l ?></option><?php endforeach;?></select></div><div class="full"><label>Catatan PU</label><textarea name="catatan" placeholder="Catatan pemeriksaan, perbaikan, atau keputusan..."><?= htmlspecialchars($row['catatan_admin']?:'') ?></textarea></div></div><button class="btn btn-primary" style="margin-top:20px">Simpan Tahap</button><?= form_close() ?>

<?php if(!empty($riwayat)):?><h2 class="section-title">Riwayat Tahapan</h2><div class="table-wrap"><table style="min-width:700px"><thead><tr><th>Tanggal</th><th>Tahap</th><th>Status</th><th>Catatan</th><th>Petugas PU</th></tr></thead><tbody><?php foreach($riwayat as $r):?><tr><td><?= date('d/m/Y H:i',strtotime($r['created_at'])) ?></td><td><?= $r['tahap'] ?></td><td><?= ucfirst($r['status']) ?></td><td><?= htmlspecialchars($r['keterangan']) ?></td><td><?= htmlspecialchars($r['actor']) ?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div>
<?php $this->load->view('pbg_pu/footer'); ?>
